typedef unsigned char u_char;
typedef unsigned int u_int;

extern "C" char *strcpy(char *, const char *);
extern "C" char *strcat(char *, const char *);

class stringx
{
  char *chars;
  void *my_buf;
public:
  stringx(const char *);
  ~stringx();
};

struct stash_index_entry;

namespace stash
{
  bool is_stash_open();
}

class app_file
{
public:
  app_file();
  ~app_file();
  bool get_memory_image(const char *, unsigned char *&, unsigned int &,
                        stash_index_entry *&, int alignment = 1);
  int get_size();
  bool read(void *, int);
  void close();
};

void* KSMemAllocate(u_int Size, u_int Align, const char *file, int line);

class world_dynamics_system
{
public:
  static bool wds_exists(const stringx &, const stringx &, int flags = 0);
  static stringx wds_open(app_file &, const stringx &, const stringx &, int io_flags = 1);
  static bool wds_readfile(const char *, unsigned char **, unsigned int *, int, int);
};

bool world_dynamics_system::wds_readfile( const char *name, unsigned char **buf, unsigned int *len, int alignment, int extra_bytes )
{
	static char Work[256];

	strcpy( Work, "");
	strcat( Work, name );

	stringx work=Work;
	stringx ext="";

	if ( wds_exists(work,ext) )
	{
		app_file ChunkU;
		stash_index_entry *hdr;

		if ( !stash::is_stash_open() || !ChunkU.get_memory_image( Work, *buf, *len, hdr, alignment ) )
		{
			app_file ChunkU;

			wds_open(ChunkU,work,ext);

			*len = ChunkU.get_size();
			if ( *len )
			{
#ifdef TARGET_PS2
				// ps2 only reads in 32-byte chunks, rounding down, so we need to read in the extra on our own.
				*buf = (u_char*)KSMemAllocate( ( *len + 31 + extra_bytes ) & ~31, alignment, name, 99999  );
				ChunkU.read( *buf, ( *len + 31 ) & ~31 );
#else
				*buf = (u_char*)KSMemAllocate( *len + extra_bytes, alignment, name, 99999  );
				ChunkU.read( *buf, *len );
#endif
			}
			ChunkU.close();
		}

		return (*len)>0;
	}
	return false;
}
